/*
Number Value Writer Functions 5x5 dot Matrix - Svenofnine
https://www.shadertoy.com/view/4XyyWz
*/

#define rotate2d(a) mat2(cos(a),-sin(a),sin(a),cos(a))

const 
uint[] pattern = uint[12] (
  15255086u,                   // "0" =(14u<<20) + (17u<<15) + (17u<<10) + (17u<<5) + 14u;
  12718222u,                   // "1" =(12u<<20) +  (4u<<15) +  (4u<<10) +  (4u<<5) + 14u;
  31504927u,                   // "2" =(30u<<20) +  (1u<<15) + (14u<<10) + (16u<<5) + 31u;
  31504446u,                   // "3" =(30u<<20) +  (1u<<15) + (14u<<10) +  (1u<<5) + 30u;
  19496002u,                   // "4" =(18u<<20) + (18u<<15) + (31u<<10) +  (2u<<5) +  2u;
  33060926u,                   // "5" =(31u<<20) + (16u<<15) + (30u<<10) +  (1u<<5) + 30u;
  15235630u,                   // "6" =(14u<<20) + (16u<<15) + (30u<<10) + (17u<<5) + 14u;
  32540808u,                   // "7" =(31u<<20) +  (1u<<15) +  (2u<<10) +  (4u<<5) +  8u;
  15252014u,                   // "8" =(14u<<20) + (17u<<15) + (14u<<10) + (17u<<5) + 14u;
  15252526u,                   // "9" =(14u<<20) + (17u<<15) + (15u<<10) +  (1u<<5) + 14u;
  4u,                          // "." =4u;
  31744u                       // "-" =31u<<10;
);

float write_digit(vec2 uv, vec2 pos, float digit_id) {  
    vec2 d = uv-pos;
    uint bits = pattern[int(digit_id)];             
    float o = .0;
    // between which four dot matrix pixels of the character does uv go through?
    uint ax = uint(5.-d.x*6.25);                     
    uint ay = uint(d.y*6.25 - 1.);
    if(ay<5u)
        for(uint y=ay; y<=ay+1u; y++)
            for(uint x=ax; x<=min(ax+1u,4u); x++)
              if( ( bits & ( 1u<<(y*5u+x) ) ) > 0u)
                  o += smoothstep( .16, .03, distance( d, .16 * vec2( uvec2(5u-x, 1u+y) ) ) );    
    return o;
}

// writes the value of an float in a grid, every character in a square 1x1
// uv = frag coordinate, ofs = position bottom left corner of number, n = number to be written
float write_float(vec2 uv, vec2 ofs, float n, int right_digits) {                                          
    float ld = max(1.,ceil(log(abs(n))/log(10.)));  // left digits (from the dot)
    float rd = clamp(float(right_digits),0.,8.);    // right digits (from the dot)
    float cc =  ld+rd+1.;                           // total characters in number
    int id = -1;                                    // id of the character which will be written
    vec2 d = floor( uv - ofs );                     // distance between uv (fragment) and bottom left corner of number
    float xc = 0.;                                  // x-cursor - position in the string
    if( n<0.) {                                     // if number is smaller than 0 then it's negative
        if(d.x == xc) id = 11;  // "-"              //    set character to 11 = minus sign at cursor
        n = abs(n);                                 //    get rid of the sign
        cc++;                                       //    add a character at the end ("-" makes it longer)
        xc++;                                       //    next character in string
    }
    // the digits left of the point
    float p = pow(10., ld-1.);                      // power: gives 1000. for if ld=4, 100. if ld=3 and so on
    while( (p>0.1) && (id==-1) ) {                  // as long as power >=1 and id wasn't changed yet
        if(d.x == xc) id = int(floor(n/p));         //    set character "0".."9" at cursor 
        n = mod(n,p); p /= 10.;                     //    ret rid of the biggest digit, shorten power by one "0", 
        xc++;                                       //    next character in string
    }
    // add the point "." 
    if( (id==-1) && (d.x==xc) ) id = 10;            // if id wasn't changed yet set character "." (dot) at cursor
    xc++;                                           // next character in string
    while( (xc < cc) && (id==-1) ){                 // as long as not the end of the string and id wasn't changed yet
        n = fract(n)*10.;                           //    get a digit from right
        if(d.x == xc) id = int(floor(n));           //    set character "0".."9" at cursor 
        xc++;                                       //    next character in string
    }
    // create the digit at cursor position
    uint bits = id==-1 ? 0u : pattern[id];
    d = uv - ofs - vec2(d.x,0.);
    // between which four dot matrix pixels of the character does uv go through?
    uint ax = uint(5.-d.x*6.25);                     
    uint ay = uint(d.y*6.25 - 1.);      
    float o = .0;
    if(ay<5u)
        for(uint y=ay; y<=ay+1u; y++)
            for(uint x=ax; x<=min(ax+1u,4u); x++)
              if( ( bits & ( 1u<<(y*5u+x) ) ) > 0u)
                  o += smoothstep( .16, .03, distance( d, .16 * vec2( uvec2(5u-x, 1u+y) ) ) );
    return o;
}

// writes the value of an integer in a grid, every character in a square 1x1
// uv = frag coordinate, ofs = position bottom left corner of number, n = number to be written
float write_int(vec2 uv, vec2 ofs, int n) {
    if(n < -2147483647) return 0.;
    float xc = 0.;                                  // x-cursor - position in the string
    int id = -1;                                    // id of the character which will be written
    int p = 1000000000;                             // power - the weight of the biggest digit
    while(abs(n)<p)p/=10;                           // abs() is the reason why this function can't handle -2147483648 !!
    // d = coordinates of the character hit by uv   
    vec2 d = floor(uv-ofs);                         // first we need just the bottom left of each place        
    // 1) sign "+" or "-"
    if( n<0 ) {                                     // if number is smaller than 0 then it's negative
        if( d.x==xc ) id=11;                      //    set character to 11 = minus sign at cursor
        n = abs(n);                                 //    get rid of the sign
        xc++;                                       //    next character in string
    }
    // the digits...
    while( (p>1) && (id==-1) ) {
        if( d.x==xc) id=int(float(n/p));            // set character "0".."9" at cursor 
        n = n%p; p /= 10;                           //    get rid of the biggest digit, shorten power by one "0", 
        xc++;                                       //    next character in string
    }
    if( (id==-1) && (d.x==xc)) id=int(float(n));  
    // create the digit at cursor position
    uint bits = id==-1 ? 0u : pattern[id];
    // o = output value
    float o = .0;
    d = uv - ofs - vec2(d.x,.0);                    // d = coordinates within that one character
    // between which four dot matrix pixels of the character does uv go through?
    uint ax = uint(5.-d.x*6.25);                     
    uint ay = uint(d.y*6.25 - 1.);
    if(ay<5u)
        for(uint y=ay; y<=ay+1u; y++)
            for(uint x=ax; x<=min(ax+1u,4u); x++)
              if( ( bits & ( 1u<<(y*5u+x) ) ) > 0u)
                  o += smoothstep( .16, .03, distance( d, .16 * vec2( uvec2(5u-x, 1u+y) ) ) );
    return o;
}

// Show what's the purpose for this
void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec2 uv = fragCoord/iResolution.y;
    vec2 center = .5*(iResolution.xy/iResolution.y);

    float angle = iTime*.1;
    fragColor.rgb = vec3(
        write_float((uv-center)*10.*rotate2d(-angle), vec2(0.,0.), mod(angle*180./3.141592653,360.), 1 ) +
        write_float(uv*10., vec2(0.,0.), iTime,3 ) +
        write_float(uv*10., vec2(0.,1.), iTimeDelta,3 ) +
        write_int (uv*10., vec2(0.,2.), iFrame )+
        write_float(uv*20., vec2(0.,7.), sin(iTime),3 ) +
        write_float(uv*20., vec2(0.,6.), cos(iTime),3 ) +
        write_digit((uv-center)*(100.-mod(iTime,99.8))*rotate2d(6.*angle),vec2(-0.5), floor(mod(iTime,10.)))+
        write_digit(vec2(uv.x-1.,uv.y-abs(sin(iTime))*0.4)*10.,vec2(0.), floor(mod(1.+iTime,10.)))
    );
}
